mapper.update:
UPDATE SMT_AUTH_OPERATION_ATTEMPT
SET EXTERNAL_BATCH_ID = #{externalBatchId},
	EXTERNAL_COMMAND_ID = #{externalCommandId}, UPDATE_TIME = #{updatedAt}
WHERE ID = #{id} AND TARGET_ID = #{targetId}
	AND (EXTERNAL_BATCH_ID IS NULL OR EXTERNAL_BATCH_ID = #{externalBatchId})
	AND (EXTERNAL_COMMAND_ID IS NULL OR EXTERNAL_COMMAND_ID = #{externalCommandId})

UPDATE SMT_AUTH_OPERATION_ATTEMPT
SET TASK_ID = #{taskId}, STATUS = 'SUBMITTING',
	DISPATCHED_AT = NVL(DISPATCHED_AT, #{updatedAt}), UPDATE_TIME = #{updatedAt}
WHERE ID = #{id} AND TARGET_ID = #{targetId} AND LEASE_TOKEN = #{leaseToken}
	AND STATUS IN ('CLAIMED', 'SUBMITTING')
	AND (LEASE_UNTIL IS NULL OR LEASE_UNTIL > #{updatedAt})
	AND EXISTS (
		SELECT 1 FROM SMT_AUTH_OPERATION_TARGET
		WHERE ID = #{targetId} AND LEASE_TOKEN = #{leaseToken}
			AND STATE = 'EXECUTING'
	)
